// Normalize merchant names into candidate domains & deduplicate across runs
const staticData = $getWorkflowStaticData('global');
staticData.seenDomains = staticData.seenDomains || [];
const seen = new Set(staticData.seenDomains);

const items = $input.all();
const newDomains = [];
const reviewsByDomain = {};

for (const item of items) {
  const d = item.json;
  if (!d.merchantStoreName) continue;
  const slug = d.merchantStoreName.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (slug.length < 3) continue;
  const domain = slug + '.com';
  if (seen.has(domain) || reviewsByDomain[domain]) continue;
  reviewsByDomain[domain] = {
    merchantStoreName: d.merchantStoreName,
    rating: d.rating || 1,
    reviewDate: d.reviewDate || '',
    tenure: d.tenure || 'Unknown',
    churnSignals: d.churnSignals || [],
    reviewExcerpt: (d.reviewText || '').slice(0, 280)
  };
  newDomains.push(domain);
}

const batch = newDomains.slice(0, 15);
staticData.seenDomains = [...staticData.seenDomains, ...batch].slice(-500);

return [{ json: { domains: batch, reviewsByDomain } }];

// Normalize Shopify store summaries keyed by domain
return $input.all()
  .map(i => i.json)
  .filter(s => s && s.domain)
  .map(s => ({
    json: {
      domain: s.domain.toLowerCase(),
      isConfirmedShopify: Boolean(s.myshopifyDomain || s.themeName),
      myshopifyDomain: s.myshopifyDomain || '',
      themeName: s.themeName || 'Unknown',
      installedApps: (s.installedApps || []).join(', '),
      productCount: s.productCount || 0,
      currency: s.currency || 'USD'
    }
  }));

// Keep only domains with valid MX records & extract executive/direct contacts
return $input.all()
  .map(i => i.json)
  .filter(c => c && c.domain && c.mxVerification && c.mxVerification.hasValidMx)
  .map(c => ({
    json: {
      domain: c.domain.toLowerCase(),
      companyName: c.companyName || c.domain,
      mailProvider: c.mxVerification.mailProvider || 'Unknown',
      directEmails: (c.directEmails || []).map(e => e.email),
      likelyExecutiveEmails: (c.likelyExecutiveEmails || []).slice(0, 3).map(e => e.email),
      roleEmails: (c.roleEmails || []).map(e => e.email),
      linkedinProfiles: (c.socialProfiles && c.socialProfiles.linkedin) || []
    }
  }));

// Score each qualified lead (0-100) and attach original churn review context
const reviewsByDomain = $('3. Extract & Deduplicate Domains').item.json.reviewsByDomain || {};
const targetApp = $('1. Workflow Config (Set Target App)').item.json.competitorAppSlug;

return $input.all().map(item => {
  const d = item.json;
  const rev = reviewsByDomain[d.domain] || {};
  let score = 25; // Base: valid MX verified domain
  if (rev.rating === 1) score += 25; else if (rev.rating === 2) score += 15;
  if (d.isConfirmedShopify) score += 20;
  if ((d.directEmails || []).length > 0 || (d.likelyExecutiveEmails || []).length > 0) score += 20;
  if ((rev.churnSignals || []).length > 0) score += 10;

  const bestContact = (d.directEmails && d.directEmails[0]) || (d.likelyExecutiveEmails && d.likelyExecutiveEmails[0]) || (d.roleEmails && d.roleEmails[0]) || '';

  return {
    json: {
      churnIntentScore: Math.min(100, score),
      domain: d.domain,
      companyName: d.companyName || rev.merchantStoreName || d.domain,
      bestContactEmail: bestContact,
      allCandidateEmails: [...(d.directEmails || []), ...(d.likelyExecutiveEmails || [])].join(', '),
      mailProvider: d.mailProvider,
      isConfirmedShopify: d.isConfirmedShopify,
      shopifyTheme: d.themeName,
      installedApps: d.installedApps,
      productCount: d.productCount,
      competitorAppChurned: targetApp,
      reviewRating: rev.rating || '',
      merchantTenure: rev.tenure || '',
      churnSignals: (rev.churnSignals || []).join(', '),
      reviewExcerpt: rev.reviewExcerpt || '',
      linkedinUrls: (d.linkedinProfiles || []).join(', '),
      complianceNote: 'Business contact only; Data Controller responsible for GDPR/CAN-SPAM opt-out.'
    }
  };
});
